#!/usr/bin/env python3
"""底部工具条：可横向拖动滚动 + 每个按钮接真实功能。

之前快影是右侧竖排、CapCut/AM 是固定 4~5 键，按钮多了没处放也不能滑。
现在三套（capcut / am / kuaishou）统一用底部可滚动的工具条：
* 按住工具条左右拖 → 内容滚动（偏移存在 egui 临时数据里，按布局分开）
* 内容比栏宽时，底部画一条细进度条，能看出还能往哪滑
* 每个按钮都接真实动作：导入面板 / layer.new / layer.newShape / 预设库 / playback.playing
"""
from __future__ import annotations

import os
from pathlib import Path

MARKER = "EFFECTCRAFT_OURS_TRAY_SCROLL_V1"

OLD = 'if ws == "capcut" || ws == "am" {\n                    let h = 58.0;\n                    // EFFECTCRAFT_OURS_TRAY_POS_V1 — 让出底部状态行，别把提示压住\n                    let bar = egui::Rect::from_min_size(\n                        egui::pos2(screen.min.x + 10.0, screen.max.y - h - 36.0),\n                        egui::vec2(screen.width() - 20.0, h),\n                    );\n                    ui.painter().rect_filled(bar, 14.0, self.tokens.panel_bg);\n                    ui.painter().rect_stroke(\n                        bar,\n                        14.0,\n                        egui::Stroke::new(1.0, self.tokens.separator),\n                        egui::StrokeKind::Inside,\n                    );\n                    let n: usize = if ws == "am" { 5 } else { 4 };\n                    let cw = bar.width() / n as f32;\n                    for i in 0..n {\n                        let cell = egui::Rect::from_min_size(\n                            egui::pos2(bar.min.x + cw * i as f32, bar.min.y),\n                            egui::vec2(cw, bar.height()),\n                        );\n                        let (label, glyph) = match i {\n                            0 => ("导入", "\\u{ff0b}"),\n                            1 => ("文字", "T"),\n                            2 => ("形状", "\\u{25c7}"),\n                            3 => ("预设", "\\u{2605}"),\n                            _ => ("播放", "\\u{25b6}"),\n                        };\n                        let resp = ui.interact(\n                            cell,\n                            egui::Id::unique(("ours-bottom", i as u64)),\n                            egui::Sense::click(),\n                        );\n                        let hot = resp.hovered();\n                        if hot {\n                            ui.painter().rect_filled(\n                                cell.shrink(3.0),\n                                10.0,\n                                accent.gamma_multiply(0.16),\n                            );\n                        }\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y - 7.0),\n                            egui::Align2::CENTER_CENTER,\n                            glyph,\n                            Tokens::ui(17.0),\n                            if hot { accent } else { text_c },\n                        );\n                        ui.painter().text(\n                            egui::pos2(cell.center().x, cell.center().y + 11.0),\n                            egui::Align2::CENTER_CENTER,\n                            label,\n                            Tokens::ui(9.0),\n                            dim_c,\n                        );\n                        if resp.clicked() {\n                            fired = Some(i as u8);\n                        }\n                    }\n                '

NEW = 'if ws == "capcut" || ws == "am" || ws == "kuaishou" {\n                    // EFFECTCRAFT_OURS_TRAY_SCROLL_V1 — 底部工具条可横向拖动滚动，按钮全部接真实功能\n                    let h = 58.0;\n                    let bar = egui::Rect::from_min_size(\n                        egui::pos2(screen.min.x + 10.0, screen.max.y - h - 36.0),\n                        egui::vec2(screen.width() - 20.0, h),\n                    );\n                    ui.painter().rect_filled(bar, 14.0, self.tokens.panel_bg);\n                    ui.painter().rect_stroke(\n                        bar,\n                        14.0,\n                        egui::Stroke::new(1.0, self.tokens.separator),\n                        egui::StrokeKind::Inside,\n                    );\n                    let items: [(&str, &str, u8); 5] = [\n                        ("\\u{ff0b}", "导入", 0),\n                        ("T", "文字", 1),\n                        ("\\u{25c7}", "形状", 2),\n                        ("\\u{2605}", "预设", 3),\n                        ("\\u{25b6}", "播放", 4),\n                    ];\n                    let cell_w = 76.0_f32;\n                    let content_w = cell_w * items.len() as f32;\n                    let max_sx = (content_w - bar.width()).max(0.0);\n                    let scroll_id = egui::Id::new(("ours-tray-scroll", ws.clone()));\n                    let mut sx: f32 = ui\n                        .ctx()\n                        .data(|d| d.get_temp::<f32>(scroll_id).unwrap_or(0.0))\n                        .clamp(0.0, max_sx);\n                    let drag = ui.interact(\n                        bar,\n                        egui::Id::unique(("ours-tray-drag", ws.clone())),\n                        egui::Sense::click_and_drag(),\n                    );\n                    if drag.dragged() && max_sx > 0.0 {\n                        sx = (sx - drag.drag_delta().x).clamp(0.0, max_sx);\n                        ui.ctx().data_mut(|d| d.insert_temp(scroll_id, sx));\n                        ui.ctx().request_repaint();\n                    }\n                    let clip = ui.painter().with_clip_rect(bar.shrink(2.0));\n                    for (i, (glyph, label, code)) in items.iter().enumerate() {\n                        let cell = egui::Rect::from_min_size(\n                            egui::pos2(bar.min.x + i as f32 * cell_w - sx, bar.min.y),\n                            egui::vec2(cell_w, bar.height()),\n                        );\n                        if cell.max.x < bar.min.x || cell.min.x > bar.max.x {\n                            continue;\n                        }\n                        let resp = ui.interact(\n                            cell.intersect(bar),\n                            egui::Id::unique(("ours-bottom", *code as u64)),\n                            egui::Sense::click(),\n                        );\n                        let hot = resp.hovered();\n                        if hot {\n                            clip.rect_filled(\n                                cell.shrink(3.0),\n                                10.0,\n                                self.tokens.accent.gamma_multiply(0.16),\n                            );\n                        }\n                        clip.text(\n                            egui::pos2(cell.center().x, cell.center().y - 7.0),\n                            egui::Align2::CENTER_CENTER,\n                            *glyph,\n                            Tokens::ui(17.0),\n                            if hot { self.tokens.accent } else { text_c },\n                        );\n                        clip.text(\n                            egui::pos2(cell.center().x, cell.center().y + 11.0),\n                            egui::Align2::CENTER_CENTER,\n                            *label,\n                            Tokens::ui(9.0),\n                            dim_c,\n                        );\n                        if resp.clicked() && !drag.dragged() {\n                            fired = Some(*code);\n                        }\n                    }\n                    // 可滚动提示：内容比栏宽时两端画一点渐隐\n                    if max_sx > 0.0 {\n                        let track = egui::Rect::from_min_size(\n                            egui::pos2(bar.min.x + 6.0, bar.max.y - 5.0),\n                            egui::vec2(bar.width() - 12.0, 3.0),\n                        );\n                        ui.painter()\n                            .rect_filled(track, 2.0, self.tokens.separator);\n                        let frac = (bar.width() / content_w).clamp(0.0, 1.0);\n                        let tw = (track.width() * frac).max(24.0);\n                        let tx = track.min.x + (track.width() - tw) * (sx / max_sx);\n                        ui.painter().rect_filled(\n                            egui::Rect::from_min_size(\n                                egui::pos2(tx, track.min.y),\n                                egui::vec2(tw, track.height()),\n                            ),\n                            2.0,\n                            self.tokens.accent,\n                        );\n                    }\n                '


def main() -> None:
    root = Path(os.environ["EFFECTCRAFT_DIR"]).resolve()
    path = root / "crates/ui-egui/src/app/frame.rs"
    src = path.read_text(encoding="utf-8")
    if MARKER in src:
        print("tray scroll already present")
        return
    if src.count(OLD) != 1:
        raise SystemExit(f"anchor: {{src.count(OLD)}}")
    path.write_text(src.replace(OLD, NEW, 1), encoding="utf-8")
    print("bottom tray scrolls and its buttons call real actions")


if __name__ == "__main__":
    main()
